// 直式乘法：num1[i] × num2[j] 的結果落在 pos[i+j] 與 pos[i+j+1]
// 時間複雜度: O(m·n)，空間複雜度: O(m + n)
function multiply(num1, num2) {
    if (num1 === '0' || num2 === '0')
        return '0';
    const m = num1.length, n = num2.length;
    const pos = new Array(m + n).fill(0);
    for (let i = m - 1; i >= 0; i--) {
        for (let j = n - 1; j >= 0; j--) {
            const sum = (num1.charCodeAt(i) - 48) * (num2.charCodeAt(j) - 48) + pos[i + j + 1];
            pos[i + j + 1] = sum % 10;
            pos[i + j] += Math.floor(sum / 10);
        }
    }
    const result = pos.join('');
    return result[0] === '0' ? result.slice(1) : result; // 最多只會有一個前導 0
}

