// 直式乘法：num1[i] × num2[j] 的結果落在 pos[i+j] 與 pos[i+j+1]
// 時間複雜度: O(m·n)，空間複雜度: O(m + n)
char* multiply(char* num1, char* num2) {
    int m = strlen(num1), n = strlen(num2);
    if ((m == 1 && num1[0] == '0') || (n == 1 && num2[0] == '0')) return strdup("0");

    int* pos = calloc(m + n, sizeof(int));
    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            int sum = (num1[i] - '0') * (num2[j] - '0') + pos[i + j + 1];
            pos[i + j + 1] = sum % 10;
            pos[i + j] += sum / 10;
        }
    }

    int start = pos[0] == 0 ? 1 : 0;           // 最多只會有一個前導 0
    char* res = malloc(m + n - start + 1);
    int k = 0;
    for (int i = start; i < m + n; i++) res[k++] = '0' + pos[i];
    res[k] = '\0';
    free(pos);
    return res;
}

